ult":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"RESTRUCT_OOC_14","display_order":14,"label":"Debt amendment or equitisation","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"RESTRUCT_OOC_15","display_order":15,"label":"Restructuring effective","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"RESTRUCT_OOC_16","display_order":16,"label":"Monitoring","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."}],"ficc_and_modelling_notes":"Distress does not itself terminate derivatives; record contract-specific default, collateral, close-out and hedge replacement facts."},{"event_type_id":"RESTRUCT_COURT","family":"Restructuring","name":"Formal restructuring / reorganisation","illustrative_milestones":[{"milestone_definition_id":"RESTRUCT_COURT_01","display_order":1,"label":"Distress assessment","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"RESTRUCT_COURT_02","display_order":2,"label":"Procedure selection","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"RESTRUCT_COURT_03","display_order":3,"label":"Filing or application","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"RESTRUCT_COURT_04","display_order":4,"label":"Admission or opening order","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"RESTRUCT_COURT_05","display_order":5,"label":"Administrator appointed where applicable","required_by_default":false,"applicability":"Determine from selected route, contract an