alse,"applicability":"Determine from selected route, contract and jurisdiction."}],"ficc_and_modelling_notes":"Gross asset realisations differ from stakeholder recoveries; cash forecasts must respect priority and restricted cash."},{"event_type_id":"CONTINUATION","family":"Ownership","name":"Sponsor continuation vehicle / GP-led secondary","illustrative_milestones":[{"milestone_definition_id":"CONTINUATION_01","display_order":1,"label":"Portfolio review","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"CONTINUATION_02","display_order":2,"label":"Advisers","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"CONTINUATION_03","display_order":3,"label":"Asset valuation","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"CONTINUATION_04","display_order":4,"label":"Conflict process","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"CONTINUATION_05","display_order":5,"label":"Investor outreach","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"CONTINUATION_06","display_order":6,"label":"Diligence","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"CONTINUATION_07","display_order":7,"label":"Lead investor bid","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"CONTINUATION_08","display_order":8,"label":"LP election materials","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"CONTINUATION_09","display_order":9,"label":"Sell or roll elections","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"CONTINUATION_10","display_order":10,"label":"Financing","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"CONTINUATION_11","display_order":11,"label":"Transaction documents","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"CONTINUATION_12","display_order":12,"label":"Approvals","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"CONTINUATION_13","display_order":13,"label":"Settlement","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"CONTINUATION_14","display_order":14,"label":"Assets transferred to new vehicle","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."}],"ficc_and_modelling_notes":"Track selling LP cash, rolling interests, new investor funding and asset-level refinancing without double counting."},{"event_type_id":"STRATEGIC_REVIEW","family":"Programme","name":"Strategic alternatives review","illustrative_milestones":[{"milestone_definition_id":"STRATEGIC_REVIEW_01","display_order":1,"label":"Board review initiated","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"STRATEGIC_REVIEW_02","display_order":2,"label":"Advisers appointed","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_definition_id":"STRATEGIC_REVIEW_03","display_order":3,"label":"Alternatives defined","required_by_default":false,"applicability":"Determine from selected route, contract and jurisdiction."},{"milestone_defini