create table public.corporate_event_models(
 model_id text primary key,ontology_version text not null references public.corporate_event_catalogue(version),
 graph jsonb not null,revision integer not null default 1,updated_at timestamptz not null default now()
);
create table public.corporate_event_records(
 model_id text not null references public.corporate_event_models(model_id),kind text not null,record_id text not null,body jsonb not null,
 primary key(model_id,record_id)
);
create index corporate_record_kind on public.corporate_event_records(kind,model_id);
create index corporate_record_data on public.corporate_event_records using gin(body);
create table public.corporate_event_revisions(
 id bigint generated always as identity primary key,model_id text not null references public.corporate_event_models(model_id),
 revision integer not null,previous_graph jsonb,graph jsonb not null,actor uuid references auth.users(id),source_id text,
 recorded_at timestamptz not null default clock_timestamp(),unique(model_id,revision)
);
alter table public.corporate_event_catalogue enable row level security;
create policy ce_member_read on public.corporate_event_catalogue for select to authenticated using(exists(select 1 from public.pilot_members where user_id=(select auth.uid()) and enabled));
revoke all on public.corporate_event_catalogue from public,anon,authenticated;
grant select on public.corporate_event_catalogue to authenticated;
alter table public.corporate_event_models enable row level security;
create policy ce_member_read on public.corporate_event_models for select to authenticated using(exists(select 1 from public.pilot_members where user_id=(select auth.uid()) and enabled));
revoke all on public.corporate_event_models from public,anon,authenticated;
grant select on public.corporate_event_models to authenticated;
alter table public.corporate_event_records enable row level security;
create policy ce_member_read on public.corporate_event_records for select to authenticated using(exists(select 1 from public.pilot_members where user_id=(select auth.uid()) and enabled));
revoke all on public.corporate_event_records from public,anon,authenticated;
grant select on public.corporate_event_records to authenticated;
alter table public.corporate_event_revisions enable row level security;
create policy ce_member_read on public.corporate_event_revisions for select to authenticated using(exists(select 1 from public.pilot_members where user_id=(select auth.uid()) and enabled));
revoke all on public.corporate_event_revisions from public,anon,authenticated;
grant select on public.corporate_event_revisions to authenticated;

create function public.ce_ref_exists(g jsonb,identifier text,expected text default null) returns boolean language sql stable set search_path=pg_catalog,public as $$
 select exists(select 1 from jsonb_each(g->'records') k cross join lateral jsonb_array_elements(k.value) r
 where (expected is null or k.key=expected) and r->>((select schema_document->'schemas'->k.key->>'idField' from public.corporate_event_catalogue where version='1.0.0'))=identifier)
 or (expected='MilestoneDefinition' and exists(select 1 from public.corporate_event_catalogue c cross join lateral jsonb_array_elements(c.catalogue->'event_templates') t cross join lateral jsonb_array_elements(t->'illustrative_milestones') m where c.version='1.0.0' and m->>'milestone_definition_id'=identifier));
$$;
create function public.ce_check_field(v jsonb,spec jsonb,r jsonb,g jsonb,doc jsonb) returns void language plpgsql set search_path=pg_catalog,public as $$
declare typ text=spec->>'type'; value text; child jsonb; n numeric;
begin
 if v is null or v='null'::jsonb then if coalesce((spec->>'required')::boolean,false) then raise exception 'Required corporate-event field missing'; end if;return;end if;
 value=v#>>'{}';
 if typ='id' then if jsonb_typeof(v)<>'string' or value!~'^[A-Za-z0-9][A-Za-z0-9._:/-]{0,159}$' then raise exception 'Invalid corporate record ID';end if;
 elsif typ in('ref','any_ref') then if jsonb_typeof(v)<>'string' or not public.ce_ref_exists(g,value,case when typ='ref' then spec->>'ref' else null end) then raise exception 'Missing or wrongly typed corporate reference: %',value;end if;
 elsif typ='enum' then if jsonb_typeof(v)<>'string' or not(doc->'enums'->(spec->>'enum') ? value) then raise exception 'Invalid corporate enum %: %',spec->>'enum',value;end if;
 elsif typ='workstream_status' then if jsonb_typeof(v)<>'string' or not coalesce(doc->'workstreams'->(r->>'workstream_type') ? value,false) then raise exception 'State does not belong to workstream';end if;
 elsif typ='array' then
  if jsonb_typeof(v)<>'array' or jsonb_array_length(v)>200 then raise exception 'Invalid corporate array';end if;
  for child in select * from jsonb_array_elements(v) loop perform public.ce_check_field(child,jsonb_build_object('type',spec->>'items','ref',spec->>'ref','enum',spec->>'enum','required',true),r,g,doc);end loop;
 elsif typ in('decimal','percentage','probability') then
  if jsonb_typeof(v)<>'string' or value!~'^-?(0|[1-9][0-9]{0,19})(\.[0-9]{1,18})?$' then raise exception 'Exact decimal strings required';end if;n=value::numeric;
  if typ='percentage' and (n<0 or n>100) or typ='probability' and (n<0 or n>1) then raise exception 'Invalid bounded decimal';end if;
 elsif typ in('integer','score') then if jsonb_typeof(v)<>'number' or value::numeric<>trunc(value::numeric) or value::numeric<(case when typ='score' then 1 else 0 end) or value::numeric>(case when typ='score' then 5 else 9007199254740991 end) then raise exception 'Invalid integer / score';end if;
 elsif typ='boolean' then if jsonb_typeof(v)<>'boolean' then raise exception 'Invalid boolean';end if;
 elsif typ in('country','currency') then if jsonb_typeof(v)<>'string' or not(doc->'enums'->(case when typ='country' then 'iso_countries' else 'iso_currencies' end) ? value) then raise exception 'Invalid ISO country/currency';end if;
 elsif typ='datetime' then
  if jsonb_typeof(v)<>'string' then raise exception 'Invalid date';end if;
  if r->>'date_precision'='QUARTER' then if value!~'^[0-9]{4}-Q[1-4]$' then raise exception 'Invalid quarter precision';end if;return;end if;
  if r->>'date_precision'='MONTH' then if value!~'^[0-9]{4}-(0[1-9]|1[0-2])$' then raise exception 'Invalid month precision';end if;return;end if;
  if value!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}(T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,3})?(Z|[+-][0-9]{2}:[0-9]{2}))?$' then raise exception 'Invalid ISO date or precision';end if;perform value::timestamptz;
 elsif typ='json' then if length(v::text)>16000 then raise exception 'Corporate value too large';end if;
 else if jsonb_typeof(v)<>'string' or length(value)>4000 then raise exception 'Invalid corporate text';end if;
 end if;
end $$;
create function public.ce_validate_model(g jsonb) returns void language plpgsql set search_path=pg_catalog,public as $$
declare doc jsonb;k record;r jsonb;f record;identifier text;ids text[]='{}';root_found boolean=false;ev jsonb;claim jsonb;definition jsonb;support boolean;total numeric;other jsonb;choices jsonb;
begin
 select schema_document into doc from public.corporate_event_catalogue where version='1.0.0';
 if jsonb_typeof(g)<>'object' or g->>'ontology_version' is distinct from '1.0.0' or jsonb_typeof(g->'records') is distinct from 'object' or length(g::text)>170000 then raise exception 'Invalid corporate-event model / ontology';end if;
 if exists(select 1 from jsonb_object_keys(g) key where key not in('ontology_version','root_event_id','records')) then raise exception 'Unknown model field';end if;
 for k in select * from jsonb_each(g->'records') loop
  definition=doc->'schemas'->k.key;if definition is null or jsonb_typeof(k.value)<>'array' or jsonb_array_length(k.value)>200 then raise exception 'Unknown or oversized corporate collection';end if;
  for r in select * from jsonb_array_elements(k.value) loop
   if jsonb_typeof(r)<>'object' then raise exception 'Invalid corporate record';end if;
   identifier=r->>(definition->>'idField');if identifier is null or identifier=any(ids) then raise exception 'Duplicate or missing corporate ID';end if;ids=array_append(ids,identifier);
   if k.key='CorporateEvent' and identifier=g->>'root_event_id' then root_found=true;end if;
   if exists(select 1 from jsonb_object_keys(r) key where not(definition->'fields' ? key)) then raise exception 'Unknown corporate field';end if;
   for f in select * from jsonb_each(definition->'fields') loop perform public.ce_check_field(r->f.key,f.value,r,g,doc);end loop;
   if k.key='MilestoneOccurrence' then
    select m into other from public.corporate_event_catalogue c cross join lateral jsonb_array_elements(c.catalogue->'event_templates') t cross join lateral jsonb_array_elements(t->'illustrative_milestones') m where c.version='1.0.0' and m->>'milestone_definition_id'=r->>'milestone_definition_id' limit 1;
    if other is not null and not exists(select 1 from public.corporate_event_catalogue c cross join lateral jsonb_array_elements(c.catalogue->'event_templates') t cross join lateral jsonb_array_elements(t->'illustrative_milestones') m cross join lateral jsonb_array_elements(g->'records'->'CorporateEvent') event where c.version='1.0.0' and event->>'event_id'=r->>'event_id' and t->>'event_type_id'=event->>'event_type_id' and m->>'milestone_definition_id'=r->>'milestone_definition_id') then raise exception 'Milestone template mismatch';end if;
    if r->>'status' is not null and r->>'status'<>'UNKNOWN' and coalesce(jsonb_array_length(r->'source_claim_ids'),0)=0 then raise exception 'Milestone state needs supporting claims';end if;
   end if;
   if k.key='StateTransition' then
    if coalesce(jsonb_array_length(r->'supporting_claim_ids'),0)=0 then raise exception 'State transition needs claims';end if;
    choices=case r->>'dimension' when 'LIFECYCLE_PHASE' then doc->'enums'->'lifecycle_phases' when 'DISPOSITION' then doc->'enums'->'dispositions' when 'OUTCOME' then doc->'enums'->'outcomes' else null end;
    if r->>'dimension'='WORKSTREAM_STATUS' then select doc->'workstreams'->(w->>'workstream_type') into choices from jsonb_array_elements(g->'records'->'WorkstreamInstance') w where w->>'workstream_id'=r->>'workstream_id';end if;
    if (r->>'new_value' is not null and not coalesce(choices ? (r->>'new_value'),false)) or (r->>'prior_value' is not null and not coalesce(choices ? (r->>'prior_value'),false)) then raise exception 'Invalid transition state';end if;
   end if;
   if k.key='Forecast' and r->>'estimate_unit' is not null then
    other=jsonb_build_object('type',case r->>'estimate_unit' when 'PROBABILITY' then 'probability' when 'DATE' then 'datetime' else 'decimal' end);
    perform public.ce_check_field(r->'estimate',other,r,g,doc);perform public.ce_check_field(r->'low',other,r,g,doc);perform public.ce_check_field(r->'high',other,r,g,doc);
   end if;
   if k.key='Claim' and r->'value' is not null and r->'value'<>'null'::jsonb then
    choices=case r->>'predicate' when 'EVENT_TYPE' then doc->'enums'->'event_types' when 'LIFECYCLE_PHASE' then doc->'enums'->'lifecycle_phases' when 'FUNDING_STATUS' then doc->'enums'->'funding_certainties' when 'MILESTONE_STATUS' then doc->'enums'->'milestone_statuses' when 'CONDITION_STATUS' then doc->'enums'->'condition_states' when 'PARTY_ROLE' then doc->'enums'->'party_roles' when 'CONSIDERATION_CURRENCY' then doc->'enums'->'iso_currencies' when 'BUYER_FUNDING_CURRENCY' then doc->'enums'->'iso_currencies' when 'SELLER_PROCEEDS_CURRENCY' then doc->'enums'->'iso_currencies' else null end;
    if choices is not null and (jsonb_typeof(r->'value')<>'string' or not(choices ? (r->>'value'))) then raise exception 'Invalid predicate value enum';end if;
    if r->>'predicate'='EVENT_COMPLETION' and jsonb_typeof(r->'value')<>'boolean' then raise exception 'Completion claim must be boolean';end if;
   end if;
   for other in select * from jsonb_array_elements('[["expected_close_start","expected_close_end"],["expected_settlement_start","expected_settlement_end"],["effective_from","effective_to"],["valid_from","valid_to"],["start_at","end_at"],["exclusivity_start","exclusivity_end"]]'::jsonb) loop
    if (r->>(other->>0))::timestamptz>(r->>(other->>1))::timestamptz then raise exception 'Inverted date window';end if;
   end loop;
   if (r->>'allocated_notional')::numeric<0 then raise exception 'Negative allocation';end if;
   if k.key='HedgeExposureAllocation' and r->>'allocated_notional' is not null and not exists(select 1 from jsonb_array_elements(g->'records'->'Hedge') h where h->>'hedge_id'=r->>'hedge_id' and h->>'notional_currency'=r->>'currency') then raise exception 'Allocation must use contract notional currency';end if;
   if k.key='EconomicLeg' and (r->>'amount_min' is not null or r->>'amount_base' is not null or r->>'amount_max' is not null) and r->>'currency' is null then raise exception 'Monetary leg requires currency';end if;
   if k.key='RiskExposure' and r->>'notional' is not null and r->>'risk_currency' is null then raise exception 'Exposure notional requires currency';end if;
   if k.key in('Hedge','RiskExposure','FundingInstrument') and ((r->>'notional')::numeric<0 or (r->>'committed_amount')::numeric<0 or (r->>'drawn_amount')::numeric<0) then raise exception 'Negative financial notional';end if;
   if k.key='Condition' and r->>'state'='WAIVED' and (r->>'waiver_permitted')::boolean is distinct from true then raise exception 'Condition waiver is not permitted';end if;
   if k.key='EconomicLeg' then
    if (r->>'amount_min')::numeric<0 or (r->>'amount_base')::numeric<0 or (r->>'amount_max')::numeric<0 or (r->>'amount_min')::numeric>(r->>'amount_base')::numeric or (r->>'amount_base')::numeric>(r->>'amount_max')::numeric or (r->>'amount_min')::numeric>(r->>'amount_max')::numeric then raise exception 'Invalid economic amount range';end if;
   end if;
   if k.key='EventRelationship' and r->>'from_event_id'=r->>'to_event_id' then raise exception 'Self relationship';end if;
   if k.key='ClaimSupport' and not public.ce_ref_exists(g,r->>'target_id',r->>'target_type') then raise exception 'Claim support type mismatch';end if;
   if k.key='Claim' and r->>'assertion_type' is not null and (r->>'source_id' is null or coalesce(r->>'predicate','')='' or not(r ? 'value')) then raise exception 'Incomplete claim';end if;
   if k.key='Forecast' and r->>'target'='COMPLETION_PROBABILITY' then
    if r->>'estimate_unit' is distinct from 'PROBABILITY' then raise exception 'Probability requires its own unit';end if;
    perform public.ce_check_field(r->'estimate','{"type":"probability"}',r,g,doc);perform public.ce_check_field(r->'low','{"type":"probability"}',r,g,doc);perform public.ce_check_field(r->'high','{"type":"probability"}',r,g,doc);
   end if;
   if k.key='CorporateEvent' then
    if r->>'model_version' is not null and r->>'model_version'<>'1.0.0' then raise exception 'Event version mismatch';end if;
    if r->>'disposition'='COMPLETED' or r->>'lifecycle_phase'='COMPLETION' or r->>'actual_completion_at' is not null then
     select exists(select 1 from jsonb_array_elements(g->'records'->'ClaimSupport') s join lateral jsonb_array_elements(g->'records'->'Claim') c on c->>'claim_id'=s->>'claim_id' where s->>'target_id'=r->>'event_id' and c->>'predicate'='EVENT_COMPLETION' and c->>'assertion_type' in('OFFICIAL_FACT','REPORTED_FACT') and c->>'review_state'='ACCEPTED' and c->'value' in('true'::jsonb,'"COMPLETED"'::jsonb)) into support;
     if not support then raise exception 'Completion requires an accepted event_completion claim';end if;
     if exists(select 1 from jsonb_array_elements(g->'records'->'Condition') c where c->>'event_id'=r->>'event_id' and coalesce(c->>'state','UNKNOWN') not in('SATISFIED','WAIVED','NOT_APPLICABLE')) then raise exception 'Outstanding conditions prevent completion';end if;
    end if;
   end if;
   if k.key='Hedge' then select sum((a->>'allocated_notional')::numeric) into total from jsonb_array_elements(g->'records'->'HedgeExposureAllocation') a where a->>'hedge_id'=r->>'hedge_id';if total>(r->>'notional')::numeric then raise exception 'Hedge over-allocation';end if;end if;
  end loop;
 end loop;
 for f in select * from (values('EconomicLeg','leg_id','parent_leg_id'),('Claim','claim_id','supersedes_claim_id'),('MilestoneOccurrence','milestone_occurrence_id','supersedes_occurrence_id'),('StateTransition','transition_id','supersedes_transition_id')) m(kind,idkey,parentkey) loop
  if exists(with recursive edges as(select node->>f.idkey a,node->>f.parentkey b from jsonb_array_elements(g->'records'->f.kind) node where node->>f.parentkey is not null),walk(a,b,path,cycle) as(select a,b,array[a,b],a=b from edges union all select w.a,e.b,w.path||e.b,e.b=any(w.path) from walk w join edges e on e.a=w.b where not w.cycle and cardinality(w.path)<502) select 1 from walk where cycle) then raise exception 'Cyclic parent/supersession relationship';end if;
 end loop;
 if exists(with recursive edges as(select d->>'predecessor_id' a,d->>'successor_id' b from jsonb_array_elements(g->'records'->'Dependency') d),walk(a,b,path,cycle) as(select a,b,array[a,b],a=b from edges union all select w.a,e.b,w.path||e.b,e.b=any(w.path) from walk w join edges e on e.a=w.b where not w.cycle and cardinality(w.path)<502) select 1 from walk where cycle) then raise exception 'Cyclic dependency graph';end if;
 if not root_found or cardinality(ids)>500 then raise exception 'Missing root or oversized model';end if;
end $$;

create function public.ce_legacy_model(d jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,public as $$
declare records jsonb='{}';k text;claims jsonb='[]';e jsonb;i integer=0;party_role text;party_name text;party_id text;
begin
 for k in select jsonb_object_keys(schema_document->'schemas') from public.corporate_event_catalogue where version='1.0.0' loop records=jsonb_set(records,array[k],'[]');end loop;
 records=jsonb_set(records,'{CorporateEvent}',jsonb_build_array(jsonb_build_object('event_id','event-main','title',coalesce(nullif(d->>'target',''),d->'source'->>'headline','Unclassified corporate event'),'event_type_id',null,'lifecycle_phase',null,'disposition',null,'outcome','UNKNOWN','model_version','1.0.0')));
 foreach party_role in array array['BUYER','SELLER','TARGET'] loop
  party_name=d->>lower(party_role);if coalesce(trim(party_name),'')<>'' and lower(trim(party_name)) not in('unknown','undisclosed','unconfirmed','unclear') then
   party_id='legacy-'||lower(party_role);
   records=jsonb_set(records,'{Entity}',records->'Entity'||jsonb_build_array(jsonb_build_object('entity_id',party_id,'legal_name',party_name)));
   records=jsonb_set(records,'{EventParty}',records->'EventParty'||jsonb_build_array(jsonb_build_object('event_party_id','party-'||party_id,'event_id','event-main','entity_id',party_id,'role',party_role)));
  end if;
 end loop;
 if d->'source' is not null then
  records=jsonb_set(records,'{SourceDocument}',jsonb_build_array(jsonb_build_object('source_id','source-current','url_or_internal_ref',d->'source'->>'url','publication_at',d->'source'->>'timestamp','source_type','UNKNOWN')));
  records=jsonb_set(records,'{EventSource}','[{"event_source_id":"event-source","event_id":"event-main","source_id":"source-current"}]');
  for e in select * from jsonb_array_elements(coalesce(d->'evidence','[]')) loop if e->>'kind'<>'Unknown' and coalesce(e->>'value','')<>'' then claims=claims||jsonb_build_array(jsonb_build_object('claim_id','legacy-claim-'||i,'source_id','source-current','subject_id','event-main','predicate','OTHER','value',jsonb_build_object('legacy_label',e->>'label','legacy_value',e->'value'),'assertion_type',case when e->>'kind'='Fact' then 'REPORTED_FACT' else 'ANALYST_INFERENCE' end,'review_state','LEGACY_IMPORTED','effective_at',null,'observed_at',null,'evidence_excerpt',null));i=i+1;end if;end loop;
  records=jsonb_set(records,'{Claim}',claims);
 end if;
 return jsonb_build_object('ontology_version','1.0.0','root_event_id','event-main','records',records);
end $$;
create function public.ce_write_model(p_id text,g jsonb,p_source text default null) returns integer language plpgsql security definer set search_path=pg_catalog,public as $$
declare old_graph jsonb;rev integer;k record;r jsonb;doc jsonb;identifier text;
begin
 perform public.ce_validate_model(g);
 select graph,revision into old_graph,rev from public.corporate_event_models where model_id=p_id for update;
 if old_graph=g then return rev;end if;rev=coalesce(rev,0)+1;
 insert into public.corporate_event_models(model_id,ontology_version,graph,revision) values(p_id,'1.0.0',g,rev) on conflict(model_id) do update set graph=excluded.graph,revision=excluded.revision,updated_at=now();
 select schema_document into doc from public.corporate_event_catalogue where version='1.0.0';
 delete from public.corporate_event_records where model_id=p_id;
 for k in select * from jsonb_each(g->'records') loop for r in select * from jsonb_array_elements(k.value) loop identifier=r->>(doc->'schemas'->k.key->>'idField');insert into public.corporate_event_records values(p_id,k.key,identifier,r);end loop;end loop;
 insert into public.corporate_event_revisions(model_id,revision,previous_graph,graph,actor,source_id) values(p_id,rev,old_graph,g,auth.uid(),p_source);
 return rev;
end $$;
revoke all on function public.ce_write_model(text,jsonb,text) from public,anon,authenticated;
-- Historical fields are archived, not carried into the new active model.
create table public.corporate_legacy_archive(table_name text not null,row_id text not null,body jsonb not null,archived_at timestamptz not null default now(),primary key(table_name,row_id));
alter table public.corporate_legacy_archive enable row level security;
revoke all on public.corporate_legacy_archive from public,anon,authenticated;
insert into public.corporate_legacy_archive(table_name,row_id,body) select 'deals',id,to_jsonb(d) from public.deals d;
insert into public.corporate_legacy_archive(table_name,row_id,body) select 'source_items',id,to_jsonb(s) from public.source_items s;
do $$declare d record;begin for d in select id,body from public.deals loop perform public.ce_write_model(d.id,public.ce_legacy_model(d.body));end loop;end $$;
alter table public.source_items add column corporate_model_id text references public.corporate_event_models(model_id);
alter table public.source_items add column corporate_model_revision integer;
update public.source_items s set corporate_model_id=s.deal_id,corporate_model_revision=case when s.analysis=d.body then 1 else 0 end from public.deals d where d.id=s.deal_id;
update public.source_items set analysis=public.ce_legacy_model(analysis) where analysis is not null;
alter table public.review_drafts rename to legacy_review_drafts;
create table public.corporate_review_drafts(
 source_id text not null references public.source_items(id),reviewer_id uuid not null references auth.users(id),draft_text text not null check(length(draft_text)<=150000),note text not null default '' check(length(note)<=1000),base_version integer not null,revision integer not null,review_input jsonb,updated_at timestamptz not null default now(),primary key(source_id,reviewer_id)
);
create table public.corporate_source_reviews(
 source_id text not null references public.source_items(id),version integer not null,model_id text not null references public.corporate_event_models(model_id),graph jsonb not null,previous_graph jsonb,model_revision integer,reviewer_id uuid not null references auth.users(id),note text not null,review_input jsonb,update_classification text not null,source_snapshot jsonb not null,recorded_at timestamptz not null default clock_timestamp(),primary key(source_id,version)
);
create table public.corporate_field_feedback(
 id bigint generated always as identity primary key,source_id text not null,source_version integer not null,ontology_version text not null,entity_type text not null,record_id text not null,field text not null,proposed_value jsonb,corrected_value jsonb,reviewer_id uuid not null references auth.users(id),reason text not null,recorded_at timestamptz not null default clock_timestamp(),foreign key(source_id,source_version) references public.corporate_source_reviews(source_id,version)
);
create table public.corporate_announcements(id text primary key,model_id text not null references public.corporate_event_models(model_id),source_id text,headline text not null,url text,published_at timestamptz,update_classification text not null check(update_classification in('UNKNOWN','MATERIAL_UPDATE','NO_MATERIAL_CHANGE')),material boolean generated always as(case update_classification when 'MATERIAL_UPDATE' then true when 'NO_MATERIAL_CHANGE' then false else null end) stored,recorded_at timestamptz not null default now());
insert into public.corporate_announcements(id,model_id,headline,url,published_at,update_classification,recorded_at) select id,deal_id,body->>'headline',body->>'sourceUrl',(body->>'timestamp')::timestamptz,case when coalesce((body->>'material')::boolean,false) then 'MATERIAL_UPDATE' else 'NO_MATERIAL_CHANGE' end,created_at from public.deal_events;
create view public.ce_event_programme with(security_invoker=true) as select model_id, body->>'programme_id' as "programme_id", body->>'title' as "title", body->>'sponsor_entity_id' as "sponsor_entity_id", body->>'objective' as "objective", body->>'status' as "status", body->>'created_at' as "created_at", (body->>'version')::bigint as "version", body->>'programme_type' as "programme_type" from public.corporate_event_records where kind='EventProgramme';
revoke all on public.ce_event_programme from public,anon;grant select on public.ce_event_programme to authenticated;
create view public.ce_corporate_event with(security_invoker=true) as select model_id, body->>'event_id' as "event_id", body->>'programme_id' as "programme_id", body->>'event_type_id' as "event_type_id", body->>'title' as "title", body->>'lifecycle_phase' as "lifecycle_phase", body->>'disposition' as "disposition", body->>'outcome' as "outcome", body->>'legal_structure' as "legal_structure", body->'jurisdictions' as "jurisdictions", body->>'rulebook_version' as "rulebook_version", body->>'expected_close_start' as "expected_close_start", body->>'expected_close_end' as "expected_close_end", body->>'actual_completion_at' as "actual_completion_at", body->>'owner_entity_id' as "owner_entity_id", body->>'confidentiality' as "confidentiality", body->>'model_version' as "model_version", body->>'economic_purpose' as "economic_purpose", body->>'execution_route' as "execution_route", body->>'ownership_outcome' as "ownership_outcome", body->>'ownership_transition' as "ownership_transition", body->>'financing_structure' as "financing_structure", body->>'initiation' as "initiation", body->>'board_support' as "board_support", body->>'offer_obligation' as "offer_obligation", body->>'scope' as "scope", body->'consideration_types' as "consideration_types", body->>'separation_method' as "separation_method" from public.corporate_event_records where kind='CorporateEvent';
revoke all on public.ce_corporate_event from public,anon;grant select on public.ce_corporate_event to authenticated;
create view public.ce_event_relationship with(security_invoker=true) as select model_id, body->>'relationship_id' as "relationship_id", body->>'from_event_id' as "from_event_id", body->>'to_event_id' as "to_event_id", body->>'relationship_type' as "relationship_type", body->>'exclusivity_group_id' as "exclusivity_group_id", body->>'effective_from' as "effective_from", body->>'effective_to' as "effective_to" from public.corporate_event_records where kind='EventRelationship';
revoke all on public.ce_event_relationship from public,anon;grant select on public.ce_event_relationship to authenticated;
create view public.ce_entity with(security_invoker=true) as select model_id, body->>'entity_id' as "entity_id", body->>'legal_name' as "legal_name", body->>'LEI' as "LEI", body->>'registration_number' as "registration_number", body->>'domicile' as "domicile", body->>'reporting_currency' as "reporting_currency", body->>'entity_type' as "entity_type", body->>'parent_entity_id' as "parent_entity_id" from public.corporate_event_records where kind='Entity';
revoke all on public.ce_entity from public,anon;grant select on public.ce_entity to authenticated;
create view public.ce_event_party with(security_invoker=true) as select model_id, body->>'event_party_id' as "event_party_id", body->>'event_id' as "event_id", body->>'entity_id' as "entity_id", body->>'role' as "role", body->>'consortium_id' as "consortium_id", (body->>'ownership_before')::numeric as "ownership_before", (body->>'ownership_after')::numeric as "ownership_after", body->>'control_rights' as "control_rights", body->>'valid_from' as "valid_from", body->>'valid_to' as "valid_to", body->>'party_class' as "party_class" from public.corporate_event_records where kind='EventParty';
revoke all on public.ce_event_party from public,anon;grant select on public.ce_event_party to authenticated;
create view public.ce_transaction_perimeter with(security_invoker=true) as select model_id, body->>'perimeter_id' as "perimeter_id", body->>'event_id' as "event_id", body->'included_entity_ids' as "included_entity_ids", body->'excluded_entity_ids' as "excluded_entity_ids", body->'assets' as "assets", body->'geography' as "geography", (body->>'ownership_percent')::numeric as "ownership_percent", (body->>'perimeter_version')::bigint as "perimeter_version" from public.corporate_event_records where kind='TransactionPerimeter';
revoke all on public.ce_transaction_perimeter from public,anon;grant select on public.ce_transaction_perimeter to authenticated;
