insert into public.monitor_state(key,value) values('corporate_event_ontology','1.0.0') on conflict(key) do update set value=excluded.value;


create function public.save_corporate_draft(p_source text,p_text text,p_note text,p_expected integer,p_draft_revision integer,p_review_input jsonb default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare item public.source_items;d public.corporate_review_drafts;n integer;
begin
 if not exists(select 1 from public.pilot_members where user_id=auth.uid() and enabled and can_review) then raise exception 'Reviewer access required';end if;
 if length(p_text)>150000 or length(coalesce(p_note,''))>1000 or length(coalesce(p_review_input::text,''))>170000 then raise exception 'Draft too large';end if;
 select * into item from public.source_items where id=p_source for update;
 if not found or item.state not in('pending','approved') then raise exception 'Source is not editable';end if;
 if p_expected is null or item.review_version<>p_expected then raise exception 'Review changed since you opened it';end if;
 select * into d from public.corporate_review_drafts where source_id=p_source and reviewer_id=auth.uid() for update;
 if p_draft_revision is null or coalesce(d.revision,0)<>p_draft_revision then raise exception 'Draft changed in another session';end if;n=coalesce(d.revision,0)+1;
 insert into public.corporate_review_drafts(source_id,reviewer_id,draft_text,note,base_version,revision,review_input) values(p_source,auth.uid(),p_text,coalesce(p_note,''),p_expected,n,p_review_input)
 on conflict(source_id,reviewer_id) do update set draft_text=excluded.draft_text,note=excluded.note,base_version=excluded.base_version,revision=excluded.revision,review_input=excluded.review_input,updated_at=now();
 return jsonb_build_object('draftRevision',n,'saved',true);
end $$;
create function public.submit_corporate_review(p_source text,p_graph jsonb,p_note text,p_existing text,p_expected integer,p_expected_model integer,p_update_classification text,p_learning boolean,p_review_input jsonb default null)
returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare item public.source_items;mid text;current_model public.corporate_event_models;root jsonb;rev integer;source_rev integer;score integer;oid uuid;updating boolean;correcting boolean;doc jsonb;k record;r jsonb;old_r jsonb;field text;original jsonb;proposed jsonb;group_id text;old_learning text;
begin
 if not exists(select 1 from public.pilot_members where user_id=auth.uid() and enabled and can_review) then raise exception 'Reviewer access required';end if;
 select * into item from public.source_items where id=p_source for update;
 if not found or item.state not in('pending','approved') then raise exception 'Source is not editable';end if;
 if p_expected is null or item.review_version<>p_expected then raise exception 'Review changed since you opened it';end if;
 if length(coalesce(p_note,''))>1000 or length(coalesce(p_review_input::text,''))>170000 then raise exception 'Review metadata too large';end if;
 if p_update_classification is null or p_update_classification not in('UNKNOWN','MATERIAL_UPDATE','NO_MATERIAL_CHANGE') then raise exception 'Invalid update classification';end if;
 correcting=item.state='approved';if correcting and length(trim(coalesce(p_note,'')))<8 then raise exception 'Explain the correction in at least 8 characters';end if;
 perform public.ce_validate_model(p_graph);
 if not exists(select 1 from jsonb_array_elements(p_graph->'records'->'SourceDocument') s where s->>'url_or_internal_ref'=item.url and (s->>'publication_at')::timestamptz=item.published_at) then raise exception 'Review must retain the current source URL and publication time';end if;
 if not exists(select 1 from jsonb_array_elements(p_graph->'records'->'EventJurisdiction') j join lateral jsonb_array_elements(p_graph->'records'->'Claim') c on c->>'claim_id'=j->>'nexus_claim_id' where j->>'country' in('SE','NO','FI','DK','IS') and c->>'assertion_type' in('OFFICIAL_FACT','REPORTED_FACT') and c->>'review_state'='ACCEPTED' and c->>'predicate'='NORDIC_NEXUS' and c->'value' not in('null'::jsonb,'false'::jsonb,'""'::jsonb)) then raise exception 'Document an accepted source-supported Nordic nexus';end if;
 mid=case when correcting then item.corporate_model_id else coalesce(p_existing,'event-'||md5(item.id)) end;
 if correcting and p_existing is not null and p_existing<>mid then raise exception 'A historical correction cannot relink its event';end if;
 select * into current_model from public.corporate_event_models where model_id=mid for update;
 updating=not correcting or item.corporate_model_revision=current_model.revision;
 if updating and p_expected_model is distinct from coalesce(current_model.revision,0) then raise exception 'Event model changed in another session';end if;
 if not correcting and p_existing is not null and current_model.model_id is null then raise exception 'Unknown corporate model';end if;
 original=case when correcting then item.analysis else current_model.graph end;
 if updating then rev=public.ce_write_model(mid,p_graph,item.id);else rev=current_model.revision;end if;
 source_rev=item.review_version+1;
 insert into public.corporate_source_reviews(source_id,version,model_id,graph,previous_graph,model_revision,reviewer_id,note,review_input,update_classification,source_snapshot) values(item.id,source_rev,mid,p_graph,original,case when updating then rev else null end,auth.uid(),coalesce(p_note,''),p_review_input,p_update_classification,jsonb_build_object('headline',item.headline,'excerpt',item.excerpt,'url',item.url,'published_at',item.published_at,'observed_at',now()));
 select schema_document into doc from public.corporate_event_catalogue where version='1.0.0';
 proposed=coalesce(p_review_input->'original',original);
 for k in select * from jsonb_each(p_graph->'records') loop for r in select * from jsonb_array_elements(k.value) loop
  select old into old_r from jsonb_array_elements(coalesce(proposed->'records'->k.key,'[]')) old where old->>(doc->'schemas'->k.key->>'idField')=r->>(doc->'schemas'->k.key->>'idField');
  for field in select jsonb_object_keys(coalesce(old_r,'{}')||r) loop if old_r->field is distinct from r->field then
   insert into public.corporate_field_feedback(source_id,source_version,ontology_version,entity_type,record_id,field,proposed_value,corrected_value,reviewer_id,reason) values(item.id,source_rev,'1.0.0',k.key,r->>(doc->'schemas'->k.key->>'idField'),field,old_r->field,r->field,auth.uid(),coalesce(p_note,''));
  end if;end loop;
 end loop;end loop;
 for k in select * from jsonb_each(coalesce(proposed->'records','{}')) loop for old_r in select * from jsonb_array_elements(k.value) loop
  if not exists(select 1 from jsonb_array_elements(coalesce(p_graph->'records'->k.key,'[]')) current_record where current_record->>(doc->'schemas'->k.key->>'idField')=old_r->>(doc->'schemas'->k.key->>'idField')) then
   insert into public.corporate_field_feedback(source_id,source_version,ontology_version,entity_type,record_id,field,proposed_value,corrected_value,reviewer_id,reason) values(item.id,source_rev,'1.0.0',k.key,old_r->>(doc->'schemas'->k.key->>'idField'),'__record__',old_r,null,auth.uid(),coalesce(p_note,''));
  end if;
 end loop;end loop;
 update public.source_items set state='approved',analysis=p_graph,corporate_model_id=mid,corporate_model_revision=case when updating then rev else corporate_model_revision end,review_version=source_rev,reviewed_by=auth.uid(),reviewed_at=now() where id=item.id;
 select coalesce(max((o->>'ficc_score')::integer),0) into score from jsonb_array_elements(p_graph->'records'->'Opportunity') o;
 select e into root from jsonb_array_elements(p_graph->'records'->'CorporateEvent') e where e->>'event_id'=p_graph->>'root_event_id';
 if not correcting then
  insert into public.corporate_announcements(id,model_id,source_id,headline,url,published_at,update_classification) values(item.id,mid,item.id,item.headline,item.url,item.published_at,p_update_classification);
  if p_update_classification='MATERIAL_UPDATE' and score>=3 and item.published_at>=now()-interval '24 hours' then
   insert into public.notification_outbox(event_id,payload) values(item.id,jsonb_build_object('title',root->>'title','body',coalesce(root->>'event_type_id','Corporate event')||' · '||coalesce(root->>'lifecycle_phase','Unknown lifecycle'),'url','/?event='||mid,'expiresAt',item.published_at+interval '24 hours')) returning id into oid;
   insert into public.notification_deliveries(outbox_id,subscription_id) select oid,s.id from public.push_subscriptions s join public.pilot_members m on m.user_id=s.user_id where s.enabled and m.enabled and s.min_score<=score;
  end if;
 else update public.corporate_announcements set update_classification=p_update_classification where id=item.id;
 update public.notification_deliveries d set status='dead',last_error='Assessment corrected before delivery',lease_until=null where d.outbox_id in(select id from public.notification_outbox where event_id=item.id) and d.status in('queued','retry','sending');end if;
 if p_learning then
  select e->>'programme_id' into group_id from jsonb_array_elements(p_graph->'records'->'CorporateEvent') e where e->>'event_id'=p_graph->>'root_event_id';
  insert into public.review_feedback(source_id,reviewer_id,decision,reason,score,note,source_snapshot,analysis_snapshot,changed_fields) values(item.id,auth.uid(),case when score=0 then 'exclude' when score>=3 then 'useful' else 'not_useful' end,case when score=0 then 'other' when correcting then 'correction' else 'approved' end,nullif(score,0),coalesce(p_note,''),jsonb_build_object('headline',item.headline,'excerpt',item.excerpt,'url',item.url,'published_at',item.published_at,'programme_id',case when group_id is null then mid else mid||'/'||group_id end,'model_id',mid,'ontology_version','1.0.0'),p_graph,coalesce((select array_agg(distinct feedback.entity_type||'.'||feedback.field) from public.corporate_field_feedback feedback where feedback.source_id=item.id and feedback.source_version=source_rev),'{}'::text[]));
  if correcting or exists(select 1 from public.learning_settings settings join public.learning_models model on model.id=settings.active_model where settings.id=1 and settings.use_learned_ranking and model.artifact->'examples' @> jsonb_build_array(jsonb_build_object('sourceId',item.id))) then
   update public.learning_settings set use_learned_ranking=false,updated_by=auth.uid(),updated_at=now() where id=1 and use_learned_ranking returning active_model into old_learning;
   if old_learning is not null then insert into public.learning_activation_log(model_id,enabled,reviewer_id) values(old_learning,false,auth.uid());end if;
  end if;
 end if;
 delete from public.corporate_review_drafts where source_id=item.id and reviewer_id=auth.uid();
 return jsonb_build_object('saved',true,'modelId',mid,'correction',correcting,'latestModelUpdated',updating,'reviewVersion',source_rev,'modelRevision',rev,'queued',oid is not null);
end $$;
alter table public.corporate_source_reviews enable row level security;create policy ce_member_read on public.corporate_source_reviews for select to authenticated using(exists(select 1 from public.pilot_members where user_id=(select auth.uid()) and enabled));revoke all on public.corporate_source_reviews from public,anon,authenticated;grant select on public.corporate_source_reviews to authenticated;
alter table public.corporate_field_feedback enable row level security;create policy ce_member_read on public.corporate_field_feedback for select to authenticated using(exists(select 1 from public.pilot_members where user_id=(select auth.uid()) and enabled));revoke all on public.corporate_field_feedback from public,anon,authenticated;grant select on public.corporate_field_feedback to authenticated;
alter table public.corporate_announcements enable row level security;create policy ce_member_read on public.corporate_announcements for select to authenticated using(exists(select 1 from public.pilot_members where user_id=(select auth.uid()) and enabled));revoke all on public.corporate_announcements from public,anon,authenticated;grant select on public.corporate_announcements to authenticated;
alter table public.corporate_review_drafts enable row level security;
create policy ce_own_draft on public.corporate_review_drafts for select to authenticated using(reviewer_id=auth.uid() and exists(select 1 from public.pilot_members where user_id=auth.uid() and enabled and can_review));
revoke all on public.corporate_review_drafts from public,anon,authenticated;grant select on public.corporate_review_drafts to authenticated;
revoke all on function public.save_corporate_draft(text,text,text,integer,integer,jsonb) from public,anon;grant execute on function public.save_corporate_draft(text,text,text,integer,integer,jsonb) to authenticated;
revoke all on function public.submit_corporate_review(text,jsonb,text,text,integer,integer,text,boolean,jsonb) from public,anon;grant execute on function public.submit_corporate_review(text,jsonb,text,text,integer,integer,text,boolean,jsonb) to authenticated;
-- Old schemas remain audit-only; no compatibility write routes or RPCs.
alter table public.deals rename to legacy_deals;
alter table public.deal_events rename to legacy_deal_events;
revoke all on public.legacy_deals,public.legacy_deal_events from authenticated,anon;
revoke all on function public.review_source(text,jsonb,text,boolean),public.review_source_feedback(text,jsonb,text,boolean,text,text,text),public.save_review_draft(text,text,text,jsonb,integer,integer,jsonb),public.submit_review_assessment(text,jsonb,jsonb,text,text,integer,boolean,text,jsonb) from authenticated,anon,public;
-- Relevance feedback remains separate from graph-field corrections.
create function public.dismiss_corporate_source(p_source text,p_reason text,p_note text default '',p_learning boolean default false) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare item public.source_items;
begin
 if not exists(select 1 from public.pilot_members where user_id=auth.uid() and enabled and can_review) then raise exception 'Reviewer access required';end if;
 if p_reason is null or p_reason not in('not_event','non_nordic','routine','reporting','duplicate','low_ficc','stale','other') or length(coalesce(p_note,''))>1000 then raise exception 'Invalid dismissal';end if;
 select * into item from public.source_items where id=p_source for update;if not found then raise exception 'Unknown source';end if;
 if item.state='dismissed' then return jsonb_build_object('duplicate',true);end if;if item.state<>'pending' then raise exception 'Only pending items can be dismissed';end if;
 update public.source_items set state='dismissed',reviewed_by=auth.uid(),reviewed_at=now() where id=item.id;
 if p_learning then perform public.record_learning_feedback(item.id,case when p_reason in('duplicate','stale','other') then 'exclude' else 'not_useful' end,p_reason,null,coalesce(p_note,''),null);end if;
 return jsonb_build_object('dismissed',true,'feedbackRecorded',p_learning);
end $$;
revoke all on function public.dismiss_corporate_source(text,text,text,boolean) from public,anon;grant execute on function public.dismiss_corporate_source(text,text,text,boolean) to authenticated;
insert into public.learning_activation_log(model_id,enabled,reviewer_id) select active_model,false,updated_by from public.learning_settings where use_learned_ranking and active_model is not null and updated_by is not null;
update public.learning_settings set use_learned_ranking=false,updated_at=now() where use_learned_ranking;

alter table public.review_feedback drop constraint review_feedback_reason_check;
alter table public.review_feedback add constraint review_feedback_reason_check check(reason in('approved','not_ma','not_event','non_nordic','routine','reporting','duplicate','low_ficc','stale','other','correction','retracted'));
create view public.corporate_training_labels with(security_invoker=true) as
select f.*,coalesce((select max(newer.source_version) from public.corporate_field_feedback newer where newer.source_id=f.source_id and newer.entity_type=f.entity_type and newer.record_id=f.record_id and newer.field=f.field),f.source_version)=f.source_version
 and case when f.field='__record__' then not exists(select 1 from public.corporate_source_reviews latest cross join lateral jsonb_array_elements(latest.graph->'records'->f.entity_type) record where latest.source_id=f.source_id and latest.version=(select max(v.version) from public.corporate_source_reviews v where v.source_id=f.source_id) and record->>((select schema_document->'schemas'->f.entity_type->>'idField' from public.corporate_event_catalogue where version=f.ontology_version))=f.record_id)
 else not exists(select 1 from public.corporate_field_feedback deleted where deleted.source_id=f.source_id and deleted.entity_type=f.entity_type and deleted.record_id=f.record_id and deleted.field='__record__' and deleted.source_version>f.source_version) end as is_current_label,
 r.model_id,r.model_id||'/'||coalesce((select e->>'programme_id' from jsonb_array_elements(r.graph->'records'->'CorporateEvent') e where e->>'event_id'=r.graph->>'root_event_id'),'') as programme_group,
r.source_snapshot,r.recorded_at as review_recorded_at
from public.corporate_field_feedback f join public.corporate_source_reviews r on r.source_id=f.source_id and r.version=f.source_version;
revoke all on public.corporate_training_labels from public,anon;grant select on public.corporate_training_labels to authenticated;
-- Keep news relevance corrections, using canonical IDs and fine-grained field targets.
create or replace function public.record_learning_feedback(p_source text,p_decision text,p_reason text,p_score integer default null,p_note text default '',p_model text default null)
returns uuid language plpgsql security definer set search_path=pg_catalog,public as $$
declare item public.source_items;fid uuid;old_model text;group_id text;paths text[];
begin
 if not exists(select 1 from public.pilot_members where user_id=auth.uid() and enabled and can_review) then raise exception 'Reviewer access required';end if;
 select * into item from public.source_items where id=p_source for update;if not found or item.state='pending' then raise exception 'Review the source before labelling it';end if;
 if p_reason in('not_event','non_nordic','routine','reporting','low_ficc') and p_decision<>'not_useful' then raise exception 'Reason requires a not-useful label';end if;
 if p_reason in('duplicate','stale','other','retracted') and p_decision<>'exclude' then raise exception 'Reason must be excluded';end if;
 if p_reason in('correction','retracted') and length(trim(coalesce(p_note,'')))<8 then raise exception 'Explain feedback correction';end if;
 select e->>'programme_id' into group_id from jsonb_array_elements(coalesce(item.analysis->'records'->'CorporateEvent','[]')) e where e->>'event_id'=item.analysis->>'root_event_id';
 select coalesce(array_agg(distinct entity_type||'.'||field),array['FICC_SCORE']) into paths from public.corporate_field_feedback where source_id=item.id and source_version=item.review_version;
 insert into public.review_feedback(source_id,reviewer_id,decision,reason,score,note,source_snapshot,model_id,analysis_snapshot,changed_fields)
 values(item.id,auth.uid(),p_decision,p_reason,p_score,coalesce(p_note,''),jsonb_build_object('headline',item.headline,'excerpt',item.excerpt,'url',item.url,'published_at',item.published_at,'model_id',item.corporate_model_id,'programme_id',case when group_id is null then item.corporate_model_id else item.corporate_model_id||'/'||group_id end,'ontology_version','1.0.0'),p_model,item.analysis,paths) returning id into fid;
 if p_reason in('correction','retracted') or exists(select 1 from public.learning_settings s join public.learning_models m on m.id=s.active_model where s.id=1 and s.use_learned_ranking and m.artifact->'examples' @> jsonb_build_array(jsonb_build_object('sourceId',item.id))) then
  update public.learning_settings set use_learned_ranking=false,updated_by=auth.uid(),updated_at=now() where id=1 and use_learned_ranking returning active_model into old_model;
  if old_model is not null then insert into public.learning_activation_log(model_id,enabled,reviewer_id) values(old_model,false,auth.uid());end if;
 end if;
 return fid;
end $$;
alter table public.source_items drop column deal_id,drop column assessment;
alter table public.review_revisions rename to legacy_review_revisions;
create or replace function public.save_learning_model(p_id text,p_artifact jsonb) returns text
language plpgsql security definer set search_path=pg_catalog,public as $$
begin
 if not exists(select 1 from public.pilot_members where user_id=auth.uid() and enabled and can_review) then raise exception 'Reviewer access required'; end if;
 if p_artifact is null or not(p_artifact ?& array['algorithm','id','examples','evaluation']) or p_artifact->>'algorithm'<>'ficc-cases-v3' or p_artifact->>'id'<>p_id or jsonb_typeof(p_artifact->'examples')<>'array' or jsonb_array_length(p_artifact->'examples')>500 then raise exception 'Invalid model artifact'; end if;
 insert into public.learning_models(id,artifact,created_by) values(p_id,p_artifact,auth.uid()) on conflict do nothing;
 return p_id;
end $$;
revoke all on function public.save_learning_model(text,jsonb) from public,anon;
grant execute on function public.save_learning_model(text,jsonb) to authenticated;
create or replace function public.set_learning_mode(p_model text,p_enabled boolean) returns void
language plpgsql security definer set search_path=pg_catalog,public as $$
declare artifact jsonb;
begin
 if not exists(select 1 from public.pilot_members where user_id=auth.uid() and enabled and can_review) then raise exception 'Reviewer access required'; end if;
 if p_enabled then
  select m.artifact into artifact from public.learning_models m where m.id=p_model;
  if not found or artifact->>'algorithm'<>'ficc-cases-v3' or coalesce((artifact->'evaluation'->>'eligible')::boolean,false) is not true then raise exception 'This model has not passed the pilot evaluation gate'; end if;
  if exists(select 1 from jsonb_array_elements(artifact->'examples') e where not exists(select 1 from public.latest_review_feedback f where f.id::text=e->>'id' and f.decision<>'exclude' and f.reason not in('duplicate','stale','other'))) then raise exception 'Model contains superseded or excluded feedback; rebuild it'; end if;
 end if;
 update public.learning_settings set use_learned_ranking=p_enabled,active_model=case when p_enabled then p_model else active_model end,updated_by=auth.uid(),updated_at=now() where id=1;
 insert into public.learning_activation_log(model_id,enabled,reviewer_id) values(p_model,p_enabled,auth.uid());
end $$;
revoke all on function public.set_learning_mode(text,boolean) from public,anon;
grant execute on function public.set_learning_mode(text,boolean) to authenticated;


commit;
